import {
  type ReactNode,
  useState,
  useCallback,
  createContext,
  useContext,
} from 'react';

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

/* ---- Context ---- */

type ToggleGroupContextValue = {
  type: 'single' | 'multiple';
  value: string[];
  onToggle: (val: string) => void;
  variant: 'default' | 'outline';
  size: 'xs' | 's' | 'm' | 'l';
  animated: boolean;
};

const ToggleGroupContext = createContext<ToggleGroupContextValue | null>(null);

function useToggleGroup() {
  const ctx = useContext(ToggleGroupContext);
  if (!ctx) throw new Error('ToggleGroupItem must be used within <ToggleGroup>');
  return ctx;
}

/* ---- Root ---- */

export type ToggleGroupProps = {
  type?: 'single' | 'multiple';
  value?: string | string[];
  onValueChange?: (value: string | string[]) => void;
  variant?: 'default' | 'outline';
  size?: 'xs' | 's' | 'm' | 'l';
  orientation?: 'horizontal' | 'vertical';
  animated?: boolean;
  children: ReactNode;
  className?: string;
};

export function ToggleGroup({
  type = 'single',
  value: controlledValue,
  onValueChange,
  variant = 'default',
  size = 'm',
  orientation = 'horizontal',
  animated = false,
  children,
  className,
}: ToggleGroupProps) {
  const [internalValue, setInternalValue] = useState<string[]>([]);

  const value = controlledValue
    ? Array.isArray(controlledValue) ? controlledValue : [controlledValue]
    : internalValue;

  const onToggle = useCallback(
    (val: string) => {
      let next: string[];
      if (type === 'single') {
        next = value.includes(val) ? [] : [val];
      } else {
        next = value.includes(val) ? value.filter((v) => v !== val) : [...value, val];
      }

      if (onValueChange) {
        onValueChange(type === 'single' ? (next[0] ?? '') : next);
      } else {
        setInternalValue(next);
      }
    },
    [type, value, onValueChange],
  );

  return (
    <ToggleGroupContext.Provider value={{ type, value, onToggle, variant, size, animated }}>
      <div
        role="group"
        {...(animated ? { 'data-toggle-group-animate': '' } : {})}
        className={cn(
          'toggle-group',
          orientation === 'vertical' && 'toggle-group--vertical',
          variant === 'outline' && 'toggle-group--outline',
          className,
        )}
      >
        {children}
      </div>
    </ToggleGroupContext.Provider>
  );
}

/* ---- Item ---- */

export type ToggleGroupItemProps = {
  value: string;
  disabled?: boolean;
  children: ReactNode;
  className?: string;
};

export function ToggleGroupItem({ value: itemValue, disabled = false, children, className }: ToggleGroupItemProps) {
  const { value, onToggle, size, animated } = useToggleGroup();
  const isActive = value.includes(itemValue);
  const isIconOnly = typeof children !== 'string';
  const useTextSwap = animated && !isIconOnly;

  const content = useTextSwap ? (
    <span className="button__label">
      <span className="button__label-inner">
        <span className="button__text is--default" data-button-text="">{children}</span>
        <span className="button__text is--hover" data-button-text="" aria-hidden="true">{children}</span>
      </span>
    </span>
  ) : children;

  return (
    <button
      type="button"
      role="radio"
      aria-checked={isActive}
      aria-disabled={disabled || undefined}
      disabled={disabled}
      {...(useTextSwap ? { 'data-toggle-group-animate': '' } : {})}
      className={cn(
        'toggle-group__item',
        `toggle-group__item--${size}`,
        isActive && 'toggle-group__item--active',
        disabled && 'toggle-group__item--disabled',
        isIconOnly && 'toggle-group__item--icon-only',
        className,
      )}
      onClick={() => {
        if (!disabled) onToggle(itemValue);
      }}
    >
      {content}
    </button>
  );
}

/* -------------------------------------------------------------------------
   Toggle Group

   Selectable button group. Single or multiple selection.
   Extends button-group layout with active state.

   Variants: default (ghost bg), outline (border)
   Sizes:    xs, s, m, l
   Parts:    .toggle-group, .toggle-group__item
   ------------------------------------------------------------------------- */

/* ---- Container ---- */

.toggle-group {
  display: inline-flex;
  align-items: stretch;
  gap: var(--spacing-1, 4px);
  border-radius: var(--radius-md);
}

.toggle-group--vertical {
  flex-direction: column;
}

.toggle-group--outline {
  gap: 0;
}

/* ---- Item ---- */

.toggle-group__item {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-2, 8px);
  border: none;
  border-radius: var(--radius-md);
  background: none;
  color: var(--muted-foreground);
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  line-height: 1;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition:
    background-color var(--duration-150) var(--easing-in-out),
    color var(--duration-150) var(--easing-in-out);
}

.toggle-group__item:hover {
  background-color: var(--muted);
  color: var(--foreground);
}

.toggle-group__item:focus-visible {
  outline: var(--stroke-medium) solid var(--focus-ring-color);
  outline-offset: calc(-1 * var(--stroke-medium));
  border-radius: var(--radius-md);
}

/* Active — follows button primary convention */

.toggle-group__item--active {
  background-color: var(--primary);
  color: var(--primary-foreground);
}

/* Disabled */

.toggle-group__item--disabled {
  color: var(--muted-foreground);
  opacity: var(--opacity-50);
  cursor: not-allowed;
  pointer-events: none;
}

/* ---- Icon ---- */

.toggle-group__item-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1em;
  height: 1em;
}

.toggle-group__item-icon svg {
  width: 100%;
  height: 100%;
}

/* ---- Sizes ---- */

.toggle-group__item--xs { height: 1.75rem; padding: 0 var(--spacing-2); }
.toggle-group__item--s  { height: 2rem; padding: 0 var(--spacing-3); }
.toggle-group__item--m  { height: 2.5rem; padding: 0 var(--spacing-3); }
.toggle-group__item--l  { height: 3rem; padding: 0 var(--spacing-4); }

/* Icon-only (square) */
.toggle-group__item--icon-only.toggle-group__item--xs { width: 1.75rem; padding: 0; }
.toggle-group__item--icon-only.toggle-group__item--s  { width: 2rem; padding: 0; }
.toggle-group__item--icon-only.toggle-group__item--m  { width: 2.5rem; padding: 0; }
.toggle-group__item--icon-only.toggle-group__item--l  { width: 3rem; padding: 0; }

/* ---- Outline variant ---- */

.toggle-group--outline .toggle-group__item {
  border: var(--stroke-hairline) solid var(--border);
  border-radius: 0;
}

.toggle-group--outline:not(.toggle-group--vertical) .toggle-group__item + .toggle-group__item {
  margin-left: calc(-1 * var(--stroke-hairline));
}

.toggle-group--outline:not(.toggle-group--vertical) .toggle-group__item:first-child {
  border-radius: var(--radius-md) 0 0 var(--radius-md);
}

.toggle-group--outline:not(.toggle-group--vertical) .toggle-group__item:last-child {
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
}

.toggle-group--outline.toggle-group--vertical .toggle-group__item + .toggle-group__item {
  margin-top: calc(-1 * var(--stroke-hairline));
}

.toggle-group--outline.toggle-group--vertical .toggle-group__item:first-child {
  border-radius: var(--radius-md) var(--radius-md) 0 0;
}

.toggle-group--outline.toggle-group--vertical .toggle-group__item:last-child {
  border-radius: 0 0 var(--radius-md) var(--radius-md);
}

/* ---- Animation (opt-in) ---- */

.toggle-group__item-icon {
  transition: rotate var(--duration-500) cubic-bezier(0.19, 1, 0.22, 1);
}

@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  .toggle-group[data-toggle-group-animate] .toggle-group__item:hover:not(.toggle-group__item--disabled) {
    scale: 1.095;
  }

  .toggle-group[data-toggle-group-animate] .toggle-group__item:hover:not(.toggle-group__item--disabled) .toggle-group__item-icon {
    rotate: 360deg;
    transition: rotate 0.6s 0.05s cubic-bezier(0.19, 1, 0.22, 1);
  }
}

.toggle-group__item:active:not(.toggle-group__item--disabled) {
  scale: 0.925;
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .toggle-group__item,
  .toggle-group__item-icon {
    transition-duration: 0ms;
  }

  .toggle-group__item:active {
    scale: 1;
  }
}
